@startuml

class Student {
  + studentID : int
  + birthDate : date
  + birthCity : string
  + birthRegion : string
  + enrollmentYear : int
}

class Professor {
  + name : string
  + birthDate : date
  + birthCity : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : string
  + lectureHours : int
}

class Exam {
  + grade : float
}

Faculty "1" -- "0..*" Student : enrolls
Faculty "1" -- "0..*" Course : belongs to
Professor "1" -- "0..*" Course : teaches
Student "1" -- "0..*" Exam : passes
Course "1" -- "0..*" Exam : evaluated by

@enduml

